def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    opp_c = opp.count('C')
    last_opp = opp[-1]

    remaining = 100 - n

    if remaining <= 2:
        return 'D'

    if opp_c == n:
        if n < 15:
            return 'C'
        return 'D'

    if opp_c == 0:
        return 'D'

    if last_opp == 'C':
        return 'C'

    coop_rate = opp_c / n
    if coop_rate > 0.7:
        forgive = 0.3
    elif coop_rate > 0.4:
        forgive = 0.15
    else:
        forgive = 0.05

    if rng.random() < forgive:
        return 'C'
    return 'D'
